"""Editable, life-size village landmarks, with open public circulation."""
import math
import random
import bpy
from mathutils import Vector
from common import Builder, text, leaf_symbol

TAU = math.tau


def lathe(b, center, profile, mat, n=24):
    """Revolved cross section, including open or hollow ceramic profiles."""
    x, y, z = center
    verts = [(x+r*math.cos(TAU*i/n), y+r*math.sin(TAU*i/n), z+h)
             for r, h in profile for i in range(n)]
    faces = [(j*n+i, j*n+(i+1)%n, (j+1)*n+(i+1)%n, (j+1)*n+i)
             for j in range(len(profile)-1) for i in range(n)]
    b.mesh(verts, faces, mat)


def ellipse_disk(b, center, rx, ry, mat, n=72):
    x, y, z = center
    pts = [(x, y, z)] + [(x+rx*math.cos(TAU*i/n), y+ry*math.sin(TAU*i/n), z)
                          for i in range(n)]
    b.mesh(pts, [(0, 1+i, 1+(i+1)%n) for i in range(n)], mat)


def annular_sector(b, center, inner, outer, z0, z1, mat,
                   start=0, end=TAU, n=96, aspect=.8):
    cx, cy = center
    for i in range(n):
        a, c = start+(end-start)*i/n, start+(end-start)*(i+1)/n
        v = [(cx+r*math.cos(t), cy+aspect*r*math.sin(t), z)
             for z in [z0, z1] for r,t in [(inner,a),(outer,a),(outer,c),(inner,c)]]
        b.mesh(v, [(0,3,2,1),(4,5,6,7),(0,1,5,4),(1,2,6,5),(2,3,7,6),(3,0,4,7)], mat)


def hip_roof(b, cx, cy, width, depth, eave_z, rise, mat='roof_red'):
    w, d = width*.5, depth*.5
    ridge = max(0, w-d*.68)
    v = [(cx-w,cy-d,eave_z),(cx+w,cy-d,eave_z),(cx+w,cy+d,eave_z),(cx-w,cy+d,eave_z),
         (cx-ridge,cy,eave_z+rise),(cx+ridge,cy,eave_z+rise)]
    b.mesh(v, [(0,1,5,4),(1,2,5),(2,3,4,5),(3,0,4)],mat)
    b.line([v[4],v[5]],.17,mat,n=10)
    for a,c in [(0,4),(1,5),(2,5),(3,4)]:
        b.beam(v[a],v[c],.11,mat,n=8)
    for a,c in [(0,1),(1,2),(2,3),(3,0)]:
        b.beam(v[a],v[c],.10,'wood',n=6)
    # Raised, editable tile courses following the long roof faces.
    for side in [-1,1]:
        for j in range(1,10):
            t=j/10
            xext=w*(1-t)+ridge*t
            yy=cy+side*d*(1-t)
            zz=eave_z+rise*t+.027
            b.beam((cx-xext,yy,zz),(cx+xext,yy,zz),.038,mat,n=5)
        spacing=.43
        count=max(1,int(width/spacing))
        for i in range(count+1):
            u=-w+width*i/count
            top=max(-ridge,min(ridge,u*.80))
            b.beam((cx+u,cy+side*d,eave_z+.025),(cx+top,cy,eave_z+rise+.025),.023,mat,n=5)


TREE_PLACEMENTS=[]
def tree(b,x,y,h,r,rng,swing=False):
    TREE_PLACEMENTS.append({'x':x,'y':y,'z':0.,'height':h,'rotation':rng.random()*TAU,'trunk_radius':r*.16,'collider_height':h*.4})
    if swing:
        branch_z=h*.45
        b.beam((x,y,branch_z),(x+3.5,y-.3,branch_z+.12),.16,'bark',n=10,r2=.09)
        for xx in [x+1.9,x+3.0]:b.beam((xx,y-.22,branch_z+.06),(xx,y-.22,.64),.026,'fabric',n=6)
        b.box((x+2.45,y-.22,.60),(1.35,.48,.12),'wood_light')


def target(b, x, y, z=1.8, size=.72):
    # Circles lie in XZ; the center faces south at y-.10.
    b.box((x,y,z/2),(.16,.20,z),'wood')
    b.box((x,y,z), (size*2,.19,size*2),'wood_light')
    for r, mat in [(size*.90,'cream'),(size*.67,'red'),(size*.43,'cream'),(size*.18,'red')]:
        # Nested concentric surfaces with tiny depth offsets.
        yy=y-.115-(size-r)*.018
        vs=[(x,yy,z)]+[(x+r*math.cos(i*TAU/32),yy,z+r*math.sin(i*TAU/32)) for i in range(32)]
        b.mesh(vs,[(0,i+1,(i+1)%32+1) for i in range(32)],mat)
    b.beam((x-.42,y+.34,0),(x,y,z*.7),.055,'wood',n=6)
    b.beam((x+.42,y+.34,0),(x,y,z*.7),.055,'wood',n=6)


def _ichiraku_materials():
    from common import MATS
    specifications = {
        'ichiraku_cloth': ((.78,.715,.54),.91,0),
        'ichiraku_ink': ((.48,.043,.014),.88,0),
        'ichiraku_chrome': ((.43,.47,.45),.29,.84),
        'ichiraku_seat': ((.29,.035,.018),.40,0),
        'ichiraku_roof': ((.075,.255,.23),.67,.18),
        'ichiraku_roof_faded': ((.10,.285,.26),.77,.12),
        'ichiraku_plaster': ((.57,.59,.45),.92,0),
        'ichiraku_paper': ((.79,.77,.62),.87,0),
    }
    for name,(color,roughness,metallic) in specifications.items():
        if name in MATS: continue
        mat=bpy.data.materials.new(name); mat.use_nodes=True
        mat.diffuse_color=(*color,1)
        shader=mat.node_tree.nodes.get('Principled BSDF')
        shader.inputs['Base Color'].default_value=(*color,1)
        shader.inputs['Roughness'].default_value=roughness
        shader.inputs['Metallic'].default_value=metallic
        MATS[name]=mat


def _ichiraku_cloth(b,cx,width,height,index,top=3.40):
    """A sewn, double-sided cloth panel, with centimetre-scale folds."""
    def surface(x,z):
        u=(x-cx)/width+.5
        t=(top-z)/height
        fold=(.021*math.sin(u*math.tau*3.0+.22*index)
              +.025*math.exp(-((u-.13)/.047)**2)
              -.018*math.exp(-((u-.80)/.061)**2))
        return -.245+fold*(.35+.65*t)+.047*math.sin(math.pi*u)**2*math.sin(t*2.05)
    nx,nz=64,40
    front=[]
    for j in range(nz+1):
        t=j/nz
        for i in range(nx+1):
            u=i/nx; x=cx+(u-.5)*width
            z=top-height*t-.019*math.sin(math.pi*u)**2*t
            front.append((x,surface(x,z),z))
    count=len(front)
    verts=front+[(x,y+.004,z) for x,y,z in front]
    faces=[]
    for j in range(nz):
        for i in range(nx):
            a=j*(nx+1)+i
            faces.extend([(a+nx+1,a+nx+2,a+1,a),
                          (a+1+count,a+nx+2+count,a+nx+1+count,a+count)])
    boundary=list(range(nx+1))+[j*(nx+1)+nx for j in range(1,nz+1)]
    boundary+=list(range(nz*(nx+1)+nx-1,nz*(nx+1)-1,-1))
    boundary+=[j*(nx+1) for j in range(nz-1,0,-1)]
    for a,c in zip(boundary,boundary[1:]+boundary[:1]): faces.append((a,c,c+count,a+count))
    b.mesh(verts,faces,'ichiraku_cloth')
    # A folded hem has real thickness and follows the hanging surface.
    for offset in [0,.013]:
        points=[]
        for i in range(nx+1):
            u=i/nx; x=cx+(u-.5)*width
            z=top-height-.019*math.sin(math.pi*u)**2+offset
            points.append((x,surface(x,z)-.004,z))
        b.line(points,.0055,'ichiraku_cloth',n=6)
    for side in [-1,1]:
        x=cx+side*(width/2-.012)
        points=[(x,surface(x,top-height*j/nz)-.003,top-height*j/nz) for j in range(nz+1)]
        b.line(points,.0045,'ichiraku_cloth',n=6)
    return surface


