def _ichiraku_glyph(b,body,cx,cz,width,height,surface,name):
    """Editable ink geometry conformed to the folded cloth, no image plane."""
    import bmesh
    curve=bpy.data.curves.new(name,'CURVE'); curve.dimensions='2D'
    curve.resolution_u=1; curve.extrude=0; curve.fill_mode='BOTH'
    for outline in _ICHIRAKU_GLYPH_OUTLINES[body]:
        spline=curve.splines.new('POLY'); spline.points.add(len(outline)-1)
        for point,(x,y) in zip(spline.points,outline): point.co=(x,y,0,1)
        spline.use_cyclic_u=True
    ob=bpy.data.objects.new(name,curve); bpy.context.scene.collection.objects.link(ob)
    bpy.context.view_layer.update()
    mesh=bpy.data.meshes.new_from_object(ob.evaluated_get(bpy.context.evaluated_depsgraph_get()))
    xx=[v.co.x for v in mesh.vertices]; yy=[v.co.y for v in mesh.vertices]
    if not xx:
        raise RuntimeError('Reference glyph did not produce mesh: '+body)
    x0,x1=min(xx),max(xx); y0,y1=min(yy),max(yy)
    # Rectify the oblique frame's letter shape into the frontal noren panel.
    scale_x=width/max(x1-x0,.001); scale_y=height/max(y1-y0,.001)
    for v in mesh.vertices:
        v.co=(cx+(v.co.x-(x0+x1)/2)*scale_x,
              cz+(v.co.y-(y0+y1)/2)*scale_y,0)
    bm=bmesh.new(); bm.from_mesh(mesh)
    bmesh.ops.triangulate(bm,faces=list(bm.faces))
    # Bound the actual surface sample distance; curved ink must follow every
    # cloth fold without penetrating it between the triangle vertices.
    for _ in range(8):
        long_edges=[edge for edge in bm.edges if edge.calc_length()>.034]
        if not long_edges: break
        bmesh.ops.subdivide_edges(bm,edges=long_edges,cuts=1,use_grid_fill=True)
        bmesh.ops.triangulate(bm,faces=list(bm.faces))
    bm.to_mesh(mesh); bm.free()
    vertices=[(v.co.x,surface(v.co.x,v.co.y)-.004,v.co.y) for v in mesh.vertices]
    # Curve fill faces point +Z; the (x,y)->(x,z) map points them -Y.
    b.mesh(vertices,[tuple(p.vertices) for p in mesh.polygons],'ichiraku_ink')
    bpy.data.objects.remove(ob,do_unlink=True); bpy.data.meshes.remove(mesh)
    bpy.data.curves.remove(curve)


def _ichiraku_roof_panel(b,points,mat,thickness=.024):
    """Closed roof build-up with unchanged top profile and an opaque underside."""
    top=[tuple(p) for p in points]
    normal=(Vector(top[1])-Vector(top[0])).cross(Vector(top[2])-Vector(top[0]))
    order=(0,1,2,3) if normal.z>0 else (3,2,1,0)
    vertices=top+[(x,y,z-thickness) for x,y,z in top]
    faces=[order,tuple(i+4 for i in reversed(order))]
    faces += [(first,first+4,last+4,last) for first,last in zip(order,order[1:]+order[:1])]
    b.mesh(vertices,faces,mat)


def build_ichiraku():
    _ichiraku_materials()
    b=Builder('Landmark • Ichiraku Ramen')
    canopy_drop=.70
    base=(18,-144,.20)
    def world(p): return (base[0]+p[1],base[1]-p[0],base[2]+p[2])
    def label(body,p,size,mat='red',name=None):
        return text(body,world(p),size,mat,name,rotation=(math.pi/2,0,-math.pi/2))
    # Dimensions are inferred from the six stools and human figures in the
    # pre-Pain anime references. Width is 7.5 m; this is not a published plan.
    b.box((0,2.81,.045),(7.68,5.82,.09),'stone')
    for i in range(24):
        b.box((-3.585+i*.312,2.81,.105),(.301,5.72,.033),'wood_light' if i%5 else 'wood')
    b.mesh([(-3.66,-.34,.005),(3.66,-.34,.005),(3.66,.05,.121),(-3.66,.05,.121),
            (-3.66,-.34,-.025),(3.66,-.34,-.025),(3.66,.05,-.025),(-3.66,.05,-.025)],
           [(0,1,2,3),(7,6,5,4),(0,4,5,1),(1,5,6,2),(2,6,7,3),(3,7,4,0)],'stone')
    for x in [-3.75,3.75]:
        # Wainscot boards individually meet the real timber frame.
        b.box((x,2.84,.715),(.15,5.7,1.22),'sage')
        for j in range(21): b.box((x+(.008 if x>0 else -.008),.14+j*.267,.73),(.166,.249,1.20),'sage')
        b.box((x,2.80,1.38),(.19,5.76,.09),'wood_light')
        # Upper wall is split around a genuinely recessed side service window.
        b.box((x,.66,2.38-canopy_drop/2),(.17,1.35,1.91-canopy_drop),'ichiraku_plaster')
        b.box((x,4.96,2.38-canopy_drop/2),(.17,1.76,1.91-canopy_drop),'ichiraku_plaster')
        b.box((x,2.88,1.55),(.17,3.10,.29),'ichiraku_plaster')
        b.box((x,2.88,3.19-canopy_drop),(.17,3.10,.25),'ichiraku_plaster')
        for y in [1.38,4.38]: b.box((x,y,2.36-canopy_drop/2),(.24,.11,1.62-canopy_drop),'wood')
        for z in [1.61,3.08-canopy_drop]: b.box((x,2.88,z),(.24,3.11,.11),'wood')
        b.box((x-.045*(1 if x>0 else -1),2.88,2.36-canopy_drop/2),(.025,2.86,1.38-canopy_drop),'glass')
        for y in [2.13,2.88,3.63]: b.box((x, y,2.36-canopy_drop/2),(.10,.052,1.41-canopy_drop),'wood')
        b.box((x,2.88,2.30-canopy_drop/2),(.10,2.95,.045),'wood')
        b.box((x,2.88,1.56),(.39,3.20,.095),'wood_light')
        for y in [.01,5.65]: b.box((x,y,1.83-canopy_drop/2),(.205,.21,3.46-canopy_drop),'wood')
    # Rear door gives a second real route into the working aisle.
    b.box((-.66,5.65,1.80-canopy_drop/2),(6.03,.17,3.39-canopy_drop),'ichiraku_plaster')
    b.box((3.55,5.65,1.80-canopy_drop/2),(.39,.17,3.39-canopy_drop),'ichiraku_plaster')
    b.box((2.72,5.65,3.06-canopy_drop/2),(1.32,.17,.87-canopy_drop),'ichiraku_plaster')
    for x in [2.08,3.37]: b.box((x,5.62,1.42),(.10,.22,2.60),'wood')
    b.box((2.72,5.62,2.73),(1.42,.22,.11),'wood')
    b.mesh([(2.14,5.61,.121),(3.30,5.61,.121),(3.30,6.01,.005),(2.14,6.01,.005),
            (2.14,5.61,-.025),(3.30,5.61,-.025),(3.30,6.01,-.025),(2.14,6.01,-.025)],
           [(0,1,2,3),(7,6,5,4),(0,4,5,1),(1,5,6,2),(2,6,7,3),(3,7,4,0)],'stone')
    b.box((0,5.65,3.59-canopy_drop),(7.51,.19,.25),'ichiraku_plaster')
    for x in [-3.75,3.75]: b.box((x,4.10,3.53-canopy_drop),(.17,3.18,.37),'ichiraku_plaster')
    # Teal front posts and a slender lintel keep the characteristic broad opening.
    for x in [-3.75,3.75]:
        b.box((x,-.03,1.87-canopy_drop/2),(.225,.26,3.53-canopy_drop),'ichiraku_roof_faded')
