def school_facade(b,cx,cy,w,d,h,door=False):
    # All academy facades face south, with timber-framed classroom windows.
    if door:
        b.box((cx-w*.25-1.15,cy,h/2),(w*.5-2.3,d,h),'cream')
        b.box((cx+w*.25+1.15,cy,h/2),(w*.5-2.3,d,h),'cream')
        b.box((cx,cy,(h+3.2)/2),(4.60,d,h-3.2),'cream')
        b.box((cx,cy+d*.5-.18,1.6),(4.58,.25,3.2),'wood')
        b.box((cx,cy-d*.5-.04,.055),(4.65,2.0,.11),'stone')
        for x in [cx-2.4,cx+2.4]: b.box((x,cy-d*.5-.14,1.68),(.20,.22,3.36),'wood')
        b.box((cx,cy-d*.5-.13,3.34),(5.00,.24,.22),'wood')
    else: b.box((cx,cy,h/2),(w,d,h),'cream')
    for z in [.65,3.8,7.5,h-.2]:
        if z>=h: continue
        if door and z<3.2:
            length=(w-4.9)/2
            for side in [-1,1]: b.box((cx+side*(2.45+length/2),cy-d*.5-.11,z),(length,.18,.18),'wood')
        else: b.box((cx,cy-d*.5-.11,z),(w+.1,.18,.18),'wood')
    count=int((w-4)/4.1)
    for floor,z in enumerate([2.05,5.75,9.15]):
        if z+.85>h:continue
        for i in range(count):
            xx=cx-(count-1)*2.05+i*4.10
            if door and floor==0 and abs(xx-cx)<3: continue
            b.box((xx,cy-d*.5-.13,z),(2.65,.13,1.82),'wood')
            b.box((xx,cy-d*.5-.208,z),(2.40,.035,1.55),'glass')
            for dx in [-.80,0,.80]: b.box((xx+dx,cy-d*.5-.239,z),(.045,.06,1.61),'wood_light')
            b.box((xx,cy-d*.5-.24,z),(2.44,.06,.055),'wood_light')
            b.box((xx,cy-d*.5-.32,z-.94),(2.98,.52,.10),'stone')
    for x in [cx-w/2+.18,cx+w/2-.18]: b.box((x,cy-d*.5-.13,h/2),(.23,.25,h),'wood')
    hip_roof(b,cx,cy,w+2.3,d+2.2,h+.1,2.0,'roof_red')


def build_academy():
    b=Builder('Landmark • Ninja Academy')
    rng=random.Random(704)
    # The forecourt remains level and unobstructed from its southern gate.
    b.box((-92,145,.028),(64,38,.056),'road')
    school_facade(b,-92,172,42,15,10.9,door=True)
    school_facade(b,-119,162,10,24,7.2)
    school_facade(b,-65,162,10,24,7.2)
    # Central clock/crest tower and its little pagoda cap.
    b.box((-92,170,12.27),(9,9,3.2),'cream')
    hip_roof(b,-92,170,11,11,13.92,2.16,'roof_red')
    b.box((-92,165.42,12.23),(5.0,.16,2.80),'wood')
    b.box((-92,165.30,12.23),(4.70,.08,2.48),'cream')
    leaf_symbol(b,(-92,165.20,12.21),1.8,'red')
    # The entrance canopy and school name sit above a 3.2m wide-height passage.
    hip_roof(b,-92,162.88,9,4.5,3.57,1.1,'roof_red')
    for x in [-95.55,-88.45]: b.box((x,161.4,1.80),(.24,.24,3.60),'wood')
    b.box((-92,160.69,3.50),(5.0,.14,.60),'wood')
    text('忍者学校',(-92,160.595,3.48),.46,'paper','Ninja Academy entrance')
    # Courtyard low perimeter wall, with a wide central approach.
    for x,w in [(-111,22),(-73,22)]:
        b.box((x,125,.71),(w,.50,1.42),'stone')
        b.box((x,125,1.45),(w+.12,.68,.10),'roof_red')
    for x in [-124,-60]:
        b.box((x,140,.71),(.50,30,1.42),'stone')
        b.box((x,140,1.45),(.68,30.1,.10),'roof_red')
    for x in [-99,-85]:
        b.box((x,125,1.49),(.90,.90,2.98),'cream')
        b.box((x,125,3.04),(1.28,1.28,.20),'roof_red')
    # The famous tree swing remains physically accessible in the schoolyard.
    tree(b,-116,135,10.6,4.6,rng,swing=True)
    for x in [-106,-98,-90]: target(b,x,152,1.8,.60)
    # Weathered training posts and low benches.
    for x,y in [(-75,140),(-71.5,142),(-68,140)]:
        b.cyl((x,y,.75),.23,1.5,'bark',n=12)
        b.cyl((x,y,1.508),.225,.026,'wood_light',n=12)
        for z in [.7,.82,.94]: lathe(b,(x,y,z),[(.244,-.017),(.244,.017)],'fabric',n=14)
    for x,y in [(-105,134),(-79,135),(-108,157)]:
        b.box((x,y,.53),(3.2,.55,.13),'wood_light')
        for xx in [x-1.18,x+1.18]: b.box((xx,y,.26),(.17,.38,.52),'wood')
    # Two lantern posts and a bulletin board make the main entrance usable at eye level.
    for x in [-97,-87]:
        b.cyl((x,156,1.50),.055,3,'metal',n=8)
        b.box((x,156,3.0),(.45,.45,.56),'paper')
        hip_roof(b,x,156,.65,.65,3.31,.23,'roof_dark')
    b.box((-81,152,1.55),(3.0,.16,1.60),'wood')
    b.box((-81,151.89,1.55),(2.70,.05,1.31),'cream')
    for x in [-82.2,-79.8]: b.box((x,152,.68),(.13,.16,1.36),'wood')
    text('修業の心得',(-81,151.845,1.80),.30,'black','Academy bulletin')
    for j in range(5): b.box((-81,151.84,1.52-j*.13),(1.90-.2*(j%2),.012,.025),'wood')
    b.flush()
    return {'name':'Ninja Academy','entrance':(-92,125,0),
            'cameras':[{'name':'Academy schoolyard','location':(-92,129,1.70),'target':(-92,165,8.3)},
                       {'name':'Academy swing','location':(-110,130,1.65),'target':(-115,135,3.0)}]}


def build_arena():
    b=Builder('Landmark • Chunin Exam Arena')
    cx,cy=-225,90
    center=(cx,cy)
    aspect=.80
    # Entry lies due south. Every ring has the same gap from ground to lintel.
    start=-math.pi/2+.17
    end=3*math.pi/2-.17
    ellipse_disk(b,(cx,cy,.037),33.3,26.7,'earth',n=96)
    ellipse_disk(b,(cx,cy,.046),29.3,22.5,'road',n=96)
    # The stepped stands are annuli, leaving a genuine open fighting ground.
    annular_sector(b,center,32.6,34.2,.0,1.0,'stone',start,end,n=94,aspect=aspect)
    for tier in range(10):
        inner=34.2+tier*.84
        outer=inner+.84
        height=1.0+tier*.77
        annular_sector(b,center,inner,outer,0,height,'stone',start,end,n=94,aspect=aspect)
        annular_sector(b,center,inner+.24,inner+.67,height,height+.15,'wood_light',start,end,n=94,aspect=aspect)
    annular_sector(b,center,42.6,44.4,0,10.3,'stone',start,end,n=96,aspect=aspect)
    annular_sector(b,center,42.45,44.60,10.3,10.65,'cream',start,end,n=96,aspect=aspect)
    # Upper outer wall has windows between support piers, creating depth and skyline rhythm.
    for i in range(52):
        a=start+(end-start)*(i+.5)/52
        r=43.6
        x,y=cx+r*math.cos(a),cy+aspect*r*math.sin(a)
        rot=math.atan2(aspect*math.cos(a),-math.sin(a))
        b.box((x,y,11.55),(2.55,1.45,1.85),'cream',rot=rot)
        # Recessed dark timber spectator opening faces into the fighting area.
        xi,yi=cx+(r-.78)*math.cos(a),cy+aspect*(r-.78)*math.sin(a)
        b.box((xi,yi,11.66),(1.37,.08,1.16),'wood',rot=rot)
        b.box((xi-.012*math.cos(a),yi-.012*math.sin(a),11.66),(1.12,.065,.91),'black',rot=rot)
    annular_sector(b,center,42.0,45.4,12.45,12.73,'roof_teal',start,end,n=96,aspect=aspect)
    # Exterior buttresses, large stone block joints and coping.
    for i in range(32):
        a=start+(end-start)*i/31
        x,y=cx+44.7*math.cos(a),cy+aspect*44.7*math.sin(a)
        b.box((x,y,5.12),(1.30,1.9,10.24),'cream',rot=a-math.pi/2)
        b.box((x,y,10.30),(1.60,2.05,.26),'stone',rot=a-math.pi/2)
    for z in [2.1,4.2,6.3,8.4]:
        annular_sector(b,center,44.38,44.46,z,z+.055,'rock_shadow',start,end,n=96,aspect=aspect)
    # The entrance portal bridges the opening above 5.4m, with a flat approach below.
    yy=cy-35.25
    for sg in [-1,1]:
        b.box((cx+sg*7.5,yy,3.35),(1.55,3.20,6.7),'cream')
        b.box((cx+sg*7.5,yy-.05,.48),(2.20,3.5,.96),'stone')
    b.box((cx,yy,6.52),(16.7,3.4,2.24),'cream')
    hip_roof(b,cx,yy,18.6,5.0,7.66,1.48,'roof_teal')
    b.box((cx,yy-1.755,6.62),(7.1,.10,1.05),'wood')
    text('中忍試験', (cx,yy-1.825,6.62),.76,'paper','Chunin Exam Arena sign')
    b.box((cx,cy-29.8,.06),(12.8,13.4,.12),'road')
    # Half-open barred gate leaves are parked alongside the radial passage.
    for sg in [-1,1]:
        xx=cx+sg*6.4
        for j in range(8): b.beam((xx,yy-1+j*.37,.14),(xx,yy-1+j*.37,4.7),.041,'wood',n=6)
        for zz in [.40,2.50,4.55]: b.beam((xx,yy-1,zz),(xx,yy+1.59,zz),.065,'wood',n=6)
    # Spectator stairways in four radial aisles; each step rises only 0.19m.
    for a in [0,math.pi/2,math.pi,math.pi/4]:
        for j in range(40):
            r=34.05+j*.215
            zz=.99+j*.1925
            x,y=cx+r*math.cos(a),cy+aspect*r*math.sin(a)
            b.box((x,y,zz-.07),(2.0,.25,.14),'cream',rot=a-math.pi/2)
    # Inner retaining parapet and individual support posts, no barrier at the entrance.
    for i in range(60):
        a=start+(end-start)*i/59
        b.beam((cx+32.9*math.cos(a),cy+aspect*32.9*math.sin(a),1.0),
               (cx+32.9*math.cos(a),cy+aspect*32.9*math.sin(a),1.95),.045,'wood',n=6)
    pts=[(cx+32.9*math.cos(start+(end-start)*i/130),cy+aspect*32.9*math.sin(start+(end-start)*i/130),1.96) for i in range(131)]
    b.line(pts,.05,'wood',n=6)
    # Hokage spectator box centered on the north stand.
    b.box((cx,cy+31.5,9.5),(12.0,5.5,1.0),'cream')
    for x in [cx-5.5,cx-1.8,cx+1.8,cx+5.5]: b.box((x,cy+29.2,11.5),(.18,.18,3.0),'wood')
    hip_roof(b,cx,cy+31.7,13.4,7.0,13.0,1.8,'roof_red')
    b.box((cx,cy+28.77,10.3),(10.4,.09,.80),'red')
    leaf_symbol(b,(cx,cy+28.69,10.35),.69,'paper')
    # Ground-level fighter marks, boundary stones and tufts.
    for sg in [-1,1]:
        for i in range(5): b.box((cx+sg*7.5,cy-1.5+i*.65,.061),(.10,.43,.012),'cream')
    rng=random.Random(913)
    for i in range(20):
        a=rng.random()*TAU
        if abs((a-math.pi*1.5+math.pi)%TAU-math.pi)<.4:continue
        x,y=cx+30.8*math.cos(a),cy+24.2*math.sin(a)
        b.sphere((x,y,.25),(.50,.38,.36),'stone',n=8,rings=5)
    b.flush()
    return {'name':'Chunin Exam Arena','entrance':(cx,cy-39,0),
            'cameras':[{'name':'Chunin arena entrance','location':(cx,cy-41,1.7),'target':(cx,cy,4.0)},
                       {'name':'Chunin arena floor','location':(cx,cy-19,1.7),'target':(cx,cy+24,5.0)}],
            'floor_radius_m':[33.3,26.7],'entrance_clearance_m':5.4}


def build_training():
    b=Builder('Landmark • Training Ground and Memorial')
    rng=random.Random(315)
    cx,cy=225,90
    ellipse_disk(b,(cx,cy,.046),30,27,'earth',n=72)
    ellipse_disk(b,(cx-2,cy-5,.057),20,16,'road',n=64)
    # The three classic training posts, with ropes and readable cut end grain.
    for i,(x,y) in enumerate([(cx-8,cy-3),(cx,cy),(cx+8,cy-3)]):
        h=1.65+i*.06
        b.cyl((x,y,h/2),.58,h,'bark',n=18,r2=.53)
        b.cyl((x,y,h+.012),.527,.024,'wood_light',n=24)
        for r in [.10,.21,.33,.45]: lathe(b,(x,y,h+.026),[(r-.006,0),(r+.006,0)],'wood',n=24)
        for z in [.80,.86,.92,.98,1.04]: lathe(b,(x,y,z),[(.598,-.026),(.598,.026)],'fabric',n=20)
        for j in range(7):
            a=TAU*j/7
            b.beam((x+.59*math.cos(a),y+.59*math.sin(a),.08),(x+.55*math.cos(a+.02),y+.55*math.sin(a+.02),h-.08),.015,'wood',n=5)
        b.box((x,y-.555,1.34),(.39,.058,.36),'wood_light')
    for x,y in [(209,101),(215,105),(222,106)]: target(b,x,y,2.05,.75)
    # Quiet woodland pond with a naturally irregular shoreline, rock edging and reeds.
    px,py=244,107
    n=56
    edge=[]
    for i in range(n):
        a=TAU*i/n; r=1+.12*math.sin(a*3)+.055*math.sin(a*7)
        edge.append((px+10.2*r*math.cos(a),py+6.9*r*math.sin(a),.07))
    b.mesh([(px,py,.07)]+edge,[(0,1+i,1+(i+1)%n) for i in range(n)],'water')
    # Shallow layered stone banks avoid a flat polygon appearance.
    for i in range(38):
        a=TAU*i/38; r=1+.12*math.sin(a*3)+.055*math.sin(a*7)
        x,y=px+10.65*r*math.cos(a),py+7.30*r*math.sin(a)
        b.sphere((x,y,.18),(.47+rng.random()*.65,.40+rng.random()*.43,.32+rng.random()*.22),
                 'stone' if i%3 else 'rock_light',n=9,rings=5)
        if i%3==0:
            for j in range(5):
                xx,yy=x+rng.uniform(-.3,.3),y+rng.uniform(-.3,.3)
                hh=rng.uniform(.6,1.15)
                b.beam((xx,yy,.05),(xx+.07,yy,hh),.016,'grass',n=4)
                b.beam((xx+.07,yy,hh*.74),(xx+.22,yy+.08,hh*.91),.022,'leaf_light',n=4)
    for x,y in [(239,108),(249,106),(244,112)]:
        ellipse_disk(b,(x,y,.083),.34,.26,'leaf_light',n=12)
    # A small timber footbridge crosses the narrow pond inlet.
    for i in range(12): b.box((px+4.7,py-7.0+i*.40,.26),(2.2,.365,.14),'wood_light')
    for x in [px+3.63,px+5.77]:
        b.box((x,py-4.8,.15),(.16,5.4,.20),'wood')
        for y in [py-6.85,py-2.8]: b.box((x,y,.75),(.12,.12,1.50),'wood')
        b.beam((x,py-6.9,1.32),(x,py-2.8,1.32),.054,'wood',n=6)
    # Memorial stone, offering flowers and paved approach, all within the clearing.
    mx,my=215,113
    b.box((mx,my,.15),(4.0,3.1,.30),'stone')
    b.box((mx,my,.44),(3.1,2.40,.28),'rock_shadow')
    # Monolithic sloped-top slab, not a billboard.
    verts=[(mx-1.1,my-.53,.58),(mx+1.1,my-.53,.58),(mx+1.1,my+.48,.58),(mx-1.1,my+.48,.58),
           (mx-.88,my-.53,3.4),(mx+.88,my-.53,3.68),(mx+.88,my+.48,3.68),(mx-.88,my+.48,3.4)]
    b.mesh(verts,[(0,3,2,1),(0,1,5,4),(1,2,6,5),(2,3,7,6),(3,0,4,7),(4,5,6,7)],'rock_shadow')
    leaf_symbol(b,(mx,my-.56,2.79),.58,'stone')
    text('慰霊碑',(mx,my-.57,2.01),.48,'stone','Memorial Stone inscription')
    for j in range(6): b.box((mx,my-.573,1.49-j*.12),(1.24-(j%3)*.12,.014,.019),'stone')
    for x in [mx-.94,mx+.94]:
        lathe(b,(x,my-.96,.59),[(.12,0),(.15,.29),(.10,.39),(.085,.39),(.12,.04)],'metal',n=16)
        for j in range(5):
            dx=(j-2)*.06; hh=.6+rng.random()*.17
            b.beam((x,my-.96,.90),(x+dx,my-.96,hh+.70),.008,'leaf',n=5)
            b.sphere((x+dx,my-.96,hh+.70),(.07,.065,.05),'white' if j%2 else 'roof_red',n=8,rings=5)
    for i in range(9): b.box((mx+(i%2)*.12,my-3.0-i*.88,.039),(1.55,.62,.06),'stone',rot=.04*(-1)**i)
    # Woodland canopy surrounding the open exercise ground.
    for i in range(20):
        a=TAU*i/20; r=32+rng.random()*7
        x,y=cx+math.cos(a)*r,cy+math.sin(a)*r*.90
        # Maintain the southern walking approach and northeastern pond.
        if y<cy-22 and abs(x-cx)<10:continue
        tree(b,x,y,9+rng.random()*6,3.1+rng.random()*1.4,rng)
    # Low rustic fence at the western edge with intentional walking breaks.
    for i in range(8):
        x,y=193,73+i*3.5
        b.cyl((x,y,.74),.09,1.48,'wood',n=8)
        if i<7:
            for z in [.50,1.02]: b.beam((x,y,z),(x,y+3.5,z),.056,'wood',n=6)
    b.flush()
    return {'name':'Training Ground','entrance':(225,57,0),
            'cameras':[{'name':'Three training posts','location':(225,70,1.7),'target':(225,93,1.2)},
                       {'name':'Memorial stone','location':(215,105,1.7),'target':(215,113,1.8)},
                       {'name':'Training pond','location':(237,98,1.7),'target':(245,108,1.0)}]}


def build_landmarks():
    results=[build_ichiraku(),build_academy(),build_arena(),build_training()]
    return {'trees':TREE_PLACEMENTS,'landmarks':results,'cameras':[camera for item in results for camera in item.get('cameras',[])]}
